def restore_integrated_rasterizer(source):
    digest=blob(source.encode("utf-8"))
    if digest==PRE_INTEGRATED_RASTERIZER:
        return source
    assert digest==INTEGRATED_RASTERIZER, ("Unreviewed integrated GPU owner",digest)
    lines=source.split("\n")
    # Descending offsets avoid indexing changed positions on earlier lines.
    for index, successor, predecessor in reversed(_RASTERIZER_NS1_NS2_REVERSE):
        assert lines[index:index+len(successor)]==successor, "Integrated GPU hunk changed"
        lines[index:index+len(successor)]=predecessor
    restored="\n".join(lines)
    assert blob(restored.encode("utf-8"))==PRE_INTEGRATED_RASTERIZER, ("GPU predecessor mismatch")
    return restored

